  script.textContent = '(function () {\n  window.NetPlayerConfig = {\n    panelId: "netf-controls-panel",\n    speeds: [0.5, 1, 1.25, 1.5, 2],\n    hideDelayMs: 2500,\n    volumeHideDelayMs: 1500,\n    volumeLeaveDelayMs: 800,\n    centerIndicatorMs: 1000,\n    seekStepSec: 10,\n    maxSeekSteps: 60,\n    watchUrlPattern: /\\/watch\\/(\\d+)/,\n    interstitialSelector: ".nf-modal.interstitial-full-screen",\n    fullscreenSelectors: [\n      \'div[class*="VideoContainer"]\',\n      \'div[class*="watch-video-wrapper"]\',\n      \'div[class*="player-container"]\',\n    ],\n    nextEpisodeSelectors: [\n      \'button[data-uia="next-episode-seamless-button"]\',\n      \'button[data-uia="control-next"]\',\n      \'button[aria-label*="Next episode"]\',\n      \'button[aria-label*="Siguiente episodio"]\',\n    ],\n    prevEpisodeSelectors: [\n      \'button[data-uia="control-back"]\',\n      \'button[aria-label*="Previous episode"]\',\n      \'button[aria-label*="Episodio anterior"]\',\n    ],\n  };\n})();\n\n(function () {\n  window.NetPlayerIcons = {\n    play: `<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>`,\n    pause: `<svg viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>`,\n    back10: `<svg viewBox="0 0 24 24"><path d="M11 18V6l-8.5 6 8.5 6zm.5-6l8.5 6V6l-8.5 6z"/></svg>`,\n    forward10: `<svg viewBox="0 0 24 24"><path d="M13 6v12l8.5-6L13 6zM4 18l8.5-6L4 6v12z"/></svg>`,\n    volume: `<svg viewBox="0 0 24 24"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/></svg>`,\n    volumeMuted: `<svg viewBox="0 0 24 24"><path d="M16.5 12c0-1.77-1.02-3.29-2.5-4.03v2.21l2.45 2.45c.03-.2.05-.41.05-.63zm2.5 0c0 .94-.2 1.82-.54 2.64l1.51 1.51C20.63 14.91 21 13.5 21 12c0-4.28-2.99-7.86-7-8.77v2.06c2.89.86 5 3.54 5 6.71zM4.27 3L3 4.27 7.73 9H3v6h4l5 5v-6.73l4.25 4.25c-.67.52-1.42.93-2.25 1.18v2.06c1.38-.31 2.63-.95 3.69-1.81L19.73 21 21 19.73l-9-9L4.27 3zM12 4L9.91 6.09 12 8.18V4z"/></svg>`,\n    fullscreen: `<svg viewBox="0 0 24 24"><path d="M7 14H5v5h5v-2H7v-3zm-2-4h2V7h3V5H5v5zm12 7h-3v2h5v-5h-2v3zM14 5v2h3v3h2V5h-5z"/></svg>`,\n    skip: `<svg viewBox="0 0 24 24"><path d="M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z"/></svg>`,\n    close: `<svg viewBox="0 0 24 24"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>`,\n    loop: `<svg viewBox="0 0 24 24"><path d="M12 4V1L8 5l4 4V6c3.31 0 6 2.69 6 6 0 1.01-.25 1.97-.7 2.8l1.46 1.46C19.54 15.03 20 13.57 20 12c0-4.42-3.58-8-8-8zm0 14c-3.31 0-6-2.69-6-6 0-1.01.25-1.97.7-2.8L5.24 7.74C4.46 8.97 4 10.43 4 12c0 4.42 3.58 8 8 8v3l4-4-4-4v3z"/></svg>`,\n    pip: `<svg viewBox="0 0 24 24"><path d="M19 7h-8v6h8V7zm-2 4h-4V9h4v2zm4-12H3C1.9 1 1 1.9 1 3v18c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2V3c0-1.1-.9-2-2-2zm0 18H3V5h18v14z"/></svg>`,\n    prev: `<svg viewBox="0 0 24 24"><path d="M6 6h2v12H6zm3.5 6l8.5 6V6z"/></svg>`,\n    next: `<svg viewBox="0 0 24 24"><path d="M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z"/></svg>`,\n  };\n\n  window.NetPlayerIcon = function (name) {\n    return window.NetPlayerIcons[name] || "";\n  };\n})();\n\n(function () {\n  const C = window.NetPlayerConfig;\n\n  function hideInterstitial() {\n    document.querySelector(C.interstitialSelector)?.style.setProperty("display", "none");\n  }\n\n  function keySim(video, code, key) {\n    if (!video || video.tagName !== "VIDEO") return;\n    const keyCode =\n      code === "KeyS" ? 83 : code === "ArrowLeft" ? 37 : code === "ArrowRight" ? 39 : 0;\n    ["keydown", "keyup"].forEach((ev) =>\n      video.dispatchEvent(\n        new KeyboardEvent(ev, {\n          key,\n          code,\n          keyCode,\n          which: keyCode,\n          bubbles: true,\n          cancelable: true,\n        })\n      )\n    );\n  }\n\n  function findNativeButton(selectors) {\n    for (const selector of selectors) {\n      const btn = document.querySelector(selector);\n      if (btn && !btn.disabled && btn.offsetParent !== null) return btn;\n    }\n    return null;\n  }\n\n  function getVideoNumber() {\n    const match = window.location.pathname.match(C.watchUrlPattern);\n    return match ? parseInt(match[1], 10) : null;\n  }\n\n  function goToVideo(n) {\n    if (n !== null && n > 0) window.location.pathname = "/watch/" + n;\n  }\n\n  function hasEpisodeNavigation() {\n    return getVideoNumber() !== null || !!findNativeButton(C.nextEpisodeSelectors);\n  }\n\n  function goToNextEpisode() {\n    const native = findNativeButton(C.nextEpisodeSelectors);\n    if (native) {\n      native.click();\n      return true;\n    }\n    const current = getVideoNumber();\n    if (current !== null) {\n      goToVideo(current + 1);\n      return true;\n    }\n    return false;\n  }\n\n  function goToPrevEpisode() {\n    const native = findNativeButton(C.prevEpisodeSelectors);\n    if (native) {\n      native.click();\n      return true;\n    }\n    const current = getVideoNumber();\n    if (current !== null && current > 1) {\n      goToVideo(current - 1);\n      return true;\n    }\n    return false;\n  }\n\n  function getFullscreenWrapper(video) {\n    for (const selector of C.fullscreenSelectors) {\n      const el = video.closest(selector);\n      if (el) return el;\n    }\n    return video.parentElement;\n  }\n\n  function seek(video, pct) {\n    const duration = video.duration;\n    if (!duration || !isFinite(duration)) return;\n\n    const target = pct * duration;\n    const diff = target - video.currentTime;\n    const times = Math.round(Math.abs(diff) / C.seekStepSec);\n    const code = diff > 0 ? "ArrowRight" : "ArrowLeft";\n    const maxTimes = Math.min(times, C.maxSeekSteps);\n\n    for (let i = 0; i < maxTimes; i++) keySim(video, code, code);\n  }\n\n  window.NetPlayerNetflix = {\n    hideInterstitial,\n    keySim,\n    getVideoNumber,\n    goToVideo,\n    hasEpisodeNavigation,\n    goToNextEpisode,\n    goToPrevEpisode,\n    getFullscreenWrapper,\n    seek,\n  };\n})();\n\n(function initNetPlayer() {\n  const C = window.NetPlayerConfig;\n  const NF = window.NetPlayerNetflix;\n  const icon = window.NetPlayerIcon;\n\n  NF.hideInterstitial();\n\n  const video = document.querySelector("video");\n  if (!video) {\n    alert("No video found.");\n    return;\n  }\n  if (document.getElementById(C.panelId)) return;\n\n  const container = video.parentElement || document.body;\n  if (!container.style.position) container.style.position = "relative";\n  if (!container.style.overflow) container.style.overflow = "hidden";\n\n  const cleanup = [];\n  let hideTimer;\n  let volTimer;\n  let centerTimer;\n  let dragging = false;\n  let destroyed = false;\n\n  function on(target, event, handler, options) {\n    target.addEventListener(event, handler, options);\n    cleanup.push(() => target.removeEventListener(event, handler, options));\n  }\n\n  function clearHideTimer() {\n    clearTimeout(hideTimer);\n  }\n\n  function clearVolTimer() {\n    clearTimeout(volTimer);\n  }\n\n  function clearCenterTimer() {\n    clearTimeout(centerTimer);\n  }\n\n  const panel = document.createElement("div");\n  panel.id = C.panelId;\n  container.appendChild(panel);\n\n  const leftSec = document.createElement("div");\n  leftSec.className = "netf-section left";\n  const centerSec = document.createElement("div");\n  centerSec.className = "netf-section center";\n  const rightSec = document.createElement("div");\n  rightSec.className = "netf-section right";\n\n  const makeBtn = (label, opts = {}) => {\n    const b = document.createElement("button");\n    b.className = "netf-btn" + (opts.p ? " primary" : "");\n    b.title = opts.title || label;\n    b.innerHTML = opts.html || label;\n    b.onclick = opts.onClick || (() => {});\n    return b;\n  };\n\n  const back10 = makeBtn(icon("back10"), {\n    title: "Back 10s",\n    onClick: () => NF.keySim(video, "ArrowLeft", "ArrowLeft"),\n  });\n  const play = makeBtn(icon("play"), {\n    title: "Play/Pause",\n    onClick: () => {\n      video.paused ? video.play() : video.pause();\n      sync();\n    },\n  });\n  const fwd10 = makeBtn(icon("forward10"), {\n    title: "Forward 10s",\n    onClick: () => NF.keySim(video, "ArrowRight", "ArrowRight"),\n  });\n\n  const speedWrap = document.createElement("div");\n  speedWrap.className = "netf-speed-wrap";\n  const speedBtn = makeBtn(`<span class="netf-speed">${video.playbackRate}×</span>`);\n  const speedMenu = document.createElement("div");\n  speedMenu.className = "netf-speed-menu";\n  C.speeds.forEach((s) => {\n    const b = document.createElement("button");\n    b.className = "netf-btn";\n    b.textContent = s + "×";\n    b.onclick = () => {\n      video.playbackRate = s;\n      speedBtn.querySelector(".netf-speed").textContent = s + "×";\n      toggleSpeedMenu(false);\n    };\n    speedMenu.appendChild(b);\n  });\n\n  function toggleSpeedMenu(show) {\n    speedMenu.classList.toggle("show", show);\n    speedMenu.setAttribute("aria-hidden", show ? "false" : "true");\n  }\n\n  on(speedBtn, "mouseenter", () => toggleSpeedMenu(true));\n  on(speedWrap, "mouseleave", () => toggleSpeedMenu(false));\n  on(speedBtn, "click", (e) => {\n    e.stopPropagation();\n    toggleSpeedMenu(!speedMenu.classList.contains("show"));\n  });\n  on(document, "click", (e) => {\n    if (!speedWrap.contains(e.target)) toggleSpeedMenu(false);\n  });\n  speedWrap.appendChild(speedBtn);\n  speedWrap.appendChild(speedMenu);\n  toggleSpeedMenu(false);\n\n  let lastVolume = video.volume;\n  const volWrap = document.createElement("div");\n  volWrap.className = "netf-vol";\n  const volIcon = makeBtn(icon("volume"), {\n    title: "Mute/Unmute",\n    onClick: () => {\n      if (video.muted || video.volume === 0) {\n        video.muted = false;\n        video.volume = lastVolume || 0.5;\n        volIcon.innerHTML = icon("volume");\n      } else {\n        video.muted = true;\n        volIcon.innerHTML = icon("volumeMuted");\n      }\n      showVolume();\n    },\n  });\n  const volSlider = document.createElement("input");\n  volSlider.type = "range";\n  volSlider.min = 0;\n  volSlider.max = 1;\n  volSlider.step = 0.01;\n  volSlider.value = video.volume;\n\n  function setVolumeVisible(visible) {\n    volWrap.classList.toggle("show", visible);\n  }\n\n  function showVolume() {\n    clearVolTimer();\n    setVolumeVisible(true);\n    volTimer = setTimeout(() => setVolumeVisible(false), C.volumeHideDelayMs);\n  }\n\n  on(volSlider, "input", () => {\n    video.volume = parseFloat(volSlider.value);\n    video.muted = false;\n    volIcon.innerHTML = video.volume > 0 ? icon("volume") : icon("volumeMuted");\n    lastVolume = video.volume;\n  });\n  on(volWrap, "mouseenter", () => {\n    clearVolTimer();\n    setVolumeVisible(true);\n  });\n  on(volWrap, "mouseleave", () => {\n    volTimer = setTimeout(() => setVolumeVisible(false), C.volumeLeaveDelayMs);\n  });\n  on(video, "volumechange", () => {\n    if (!video.muted) {\n      volSlider.value = video.volume;\n      lastVolume = video.volume;\n      volIcon.innerHTML = video.volume > 0 ? icon("volume") : icon("volumeMuted");\n    }\n  });\n\n  volWrap.append(volIcon, volSlider);\n\n  const fs = makeBtn(icon("fullscreen"), {\n    title: "Fullscreen",\n    onClick: () => {\n      const wrapper = NF.getFullscreenWrapper(video);\n      if (!document.fullscreenElement) wrapper.requestFullscreen?.();\n      else document.exitFullscreen?.();\n    },\n  });\n  const skip = makeBtn(icon("skip"), {\n    title: "Skip Intro (S)",\n    onClick: () => NF.keySim(video, "KeyS", "KeyS"),\n  });\n  const loopBtn = makeBtn(icon("loop"), {\n    title: "Loop",\n    onClick: () => {\n      video.loop = !video.loop;\n      loopBtn.classList.toggle("primary", video.loop);\n    },\n  });\n  const pipBtn = makeBtn(icon("pip"), {\n    title: "PIP",\n    onClick: async () => {\n      try {\n        if (video !== document.pictureInPictureElement) await video.requestPictureInPicture();\n        else await document.exitPictureInPicture();\n      } catch (e) {\n        console.warn("[NetPlayer] Picture-in-Picture failed:", e);\n      }\n    },\n  });\n\n  leftSec.append(back10, play, fwd10, speedWrap, volWrap);\n  centerSec.append(loopBtn, pipBtn, skip);\n  rightSec.append(fs);\n  panel.append(leftSec, centerSec, rightSec);\n\n  const showEpisodeNav = NF.hasEpisodeNavigation();\n  let prevBtn = null;\n  let nextBtn = null;\n\n  if (showEpisodeNav) {\n    prevBtn = document.createElement("button");\n    prevBtn.className = "netf-nav-btn";\n    prevBtn.innerHTML = icon("prev");\n    prevBtn.title = "Previous";\n    prevBtn.onclick = () => NF.goToPrevEpisode();\n\n    nextBtn = document.createElement("button");\n    nextBtn.className = "netf-nav-btn";\n    nextBtn.innerHTML = icon("next");\n    nextBtn.title = "Next";\n    nextBtn.onclick = () => NF.goToNextEpisode();\n\n    container.appendChild(prevBtn);\n    container.appendChild(nextBtn);\n  }\n\n  const progress = document.createElement("div");\n  progress.className = "netf-progress";\n  const progressBar = document.createElement("div");\n  progressBar.className = "netf-progress-bar";\n  progress.appendChild(progressBar);\n  container.appendChild(progress);\n\n  const centerIndicator = document.createElement("div");\n  centerIndicator.className = "netf-center-indicator";\n  centerIndicator.innerHTML = icon("pause");\n  container.appendChild(centerIndicator);\n\n  function showControls() {\n    panel.style.opacity = "1";\n    if (prevBtn) prevBtn.style.opacity = "1";\n    if (nextBtn) nextBtn.style.opacity = "1";\n  }\n\n  function hideControls() {\n    panel.style.opacity = "0";\n    if (prevBtn) prevBtn.style.opacity = "0";\n    if (nextBtn) nextBtn.style.opacity = "0";\n  }\n\n  function startHideTimer() {\n    clearHideTimer();\n    hideTimer = setTimeout(hideControls, C.hideDelayMs);\n  }\n\n  on(container, "mouseenter", () => {\n    showControls();\n    startHideTimer();\n  });\n  on(container, "mousemove", () => {\n    showControls();\n    startHideTimer();\n  });\n  on(container, "mouseleave", () => {\n    hideControls();\n    clearHideTimer();\n  });\n\n  function updateProgress() {\n    progressBar.style.width = ((video.currentTime / video.duration) * 100 || 0) + "%";\n  }\n\n  on(video, "timeupdate", updateProgress);\n\n  function seekByMouse(e) {\n    const rect = progress.getBoundingClientRect();\n    let pct = (e.clientX - rect.left) / rect.width;\n    pct = Math.max(0, Math.min(1, pct));\n    NF.seek(video, pct);\n  }\n\n  on(progress, "mousedown", (e) => {\n    dragging = true;\n    seekByMouse(e);\n  });\n  on(document, "mousemove", (e) => {\n    if (dragging) seekByMouse(e);\n  });\n  on(document, "mouseup", () => {\n    dragging = false;\n  });\n\n  function updateNavButtons() {\n    if (!prevBtn || !nextBtn) return;\n    const cRect = container.getBoundingClientRect();\n    const vRect = video.getBoundingClientRect();\n    const relTop = vRect.top - cRect.top;\n    const relLeft = vRect.left - cRect.left;\n    prevBtn.style.top = relTop + vRect.height / 2 + "px";\n    prevBtn.style.left = relLeft + 8 + "px";\n    prevBtn.style.transform = "translateY(-50%)";\n    nextBtn.style.top = relTop + vRect.height / 2 + "px";\n    nextBtn.style.left = relLeft + vRect.width - (nextBtn.offsetWidth + 8) + "px";\n    nextBtn.style.transform = "translateY(-50%)";\n  }\n\n  if (showEpisodeNav) {\n    updateNavButtons();\n    on(window, "resize", updateNavButtons);\n    on(window, "scroll", updateNavButtons);\n    const observer = new MutationObserver(updateNavButtons);\n    observer.observe(video, { attributes: true, attributeFilter: ["style", "class"] });\n    cleanup.push(() => observer.disconnect());\n  }\n\n  function sync() {\n    play.innerHTML = video.paused ? icon("play") : icon("pause");\n    centerIndicator.innerHTML = video.paused ? icon("play") : icon("pause");\n  }\n\n  function showCenterIndicator() {\n    centerIndicator.classList.add("show");\n    clearCenterTimer();\n    centerTimer = setTimeout(() => centerIndicator.classList.remove("show"), C.centerIndicatorMs);\n  }\n\n  on(video, "play", () => {\n    sync();\n    showCenterIndicator();\n  });\n  on(video, "pause", () => {\n    sync();\n    showCenterIndicator();\n  });\n  on(video, "click", () => {\n    video.paused ? video.play() : video.pause();\n    sync();\n    showCenterIndicator();\n  });\n\n  sync();\n  updateProgress();\n  showControls();\n  startHideTimer();\n\n  function destroy() {\n    if (destroyed) return;\n    destroyed = true;\n\n    clearHideTimer();\n    clearVolTimer();\n    clearCenterTimer();\n    cleanup.forEach((fn) => fn());\n\n    panel.remove();\n    progress.remove();\n    centerIndicator.remove();\n    prevBtn?.remove();\n    nextBtn?.remove();\n  }\n\n  const close = makeBtn(icon("close"), { title: "Close Panel", onClick: destroy });\n  rightSec.append(close);\n})();\n';
